88	  function toggleStatus(status: string) {
89	    setActiveFilters({ statuses: toggleStatusFilter(activeFilters.statuses, status) });
90	  }
91	
92	  function toggleAllStatuses() {
93	    setActiveFilters({
94	      statuses: toggleAllStatusFilter(activeFilters.statuses),
95	    });
96	  }
97	
98	  return (
99	    <div className="flex h-12 shrink-0 items-center justify-end gap-2 border-b border-border bg-surface px-4">
