101	        type="button"
102	        onClick={reload}
103	        disabled={loading}
104	        aria-label="Sync board"
105	        className="flex h-8 items-center gap-2 border border-border bg-surface px-3 text-xs font-medium text-text-secondary transition-colors hover:bg-surface-subtle disabled:cursor-not-allowed disabled:opacity-50"
