157	                  onChange={() => toggleStatus(status.key)}
158	                  className="h-3 w-3 accent-primary"
159	                />
160	                <span
161	                  className="h-2 w-2 rounded-sm"
162	                  style={{ background: status.color }}
163	                  aria-hidden="true"
164	                />
