175	export function KanbanBoard() {
176	  const {
177	    features,
178	    loading,
179	    error,
180	    searchQuery,
181	    activeFilters,
182	    expandedFeatureIds,
183	    toggleFeature,
184	    setSelectedTask,
185	  } = useBoardContext();
186	
187	  const visibleFeatures = useMemo(
188	    () =>
189	      features.filter(
190	        (f) =>
191	          matchesSearch(f, searchQuery) &&
192	          matchesStatusFilter(f, activeFilters.statuses),
193	      ),
194	    [features, searchQuery, activeFilters],
195	  );
196	
197	  const columnCounts = useMemo(() => {
198	    const counts: Record<string, number> = {};
199	    for (const col of STATUS_COLUMNS) counts[col.key] = 0;
200	    for (const feature of visibleFeatures) {
201	      for (const task of feature.tasks) {
202	        if (task.status in counts) counts[task.status]++;
203	      }
204	    }
205	    return counts;
206	  }, [visibleFeatures]);
207	
208	  let content;
209	  if (loading) {
210	    content = (
211	      <div className="flex flex-1 items-center justify-center">
212	        <p className="text-sm text-text-muted">Loading board...</p>
213	      </div>
214	    );
