216	    content = (
217	      <div className="flex flex-1 items-center justify-center">
218	        <p className="text-sm text-danger">{error.message}</p>
219	      </div>
220	    );
221	  } else if (features.length === 0) {
222	    content = <EmptyState message="No features found in this workspace." />;
223	  } else if (visibleFeatures.length === 0) {
224	    content = (
225	      <EmptyState message="No features match the current search or filters." />
226	    );
227	  } else {
228	    content = (
229	      <div className="min-h-0 flex-1 overflow-auto">
230	        <div
231	          className="w-full"
232	          style={{ minWidth: MIN_COLUMN_WIDTH * STATUS_COLUMNS.length }}
233	        >
234	          <div
235	            className="sticky top-0 z-10 flex w-full border-b border-border"
236	            role="row"
237	            aria-label="Status columns"
238	          >
239	            {STATUS_COLUMNS.map((col) => (
240	              <ColumnHeader
241	                key={col.key}
242	                label={col.label}
243	                color={col.color}
244	                count={columnCounts[col.key] ?? 0}
245	              />
246	            ))}
247	          </div>
248	
249	          <div role="list" aria-label="Features" className="bg-surface">
250	            {visibleFeatures.map((feature) => (
251	              <div key={feature.id} role="listitem">
252	                <FeatureRow
253	                  feature={feature}
