255	                  onToggle={() => toggleFeature(feature.id)}
256	                  onSelectTask={setSelectedTask}
257	                  minColumnWidth={MIN_COLUMN_WIDTH}
258	                />
259	              </div>
260	            ))}
261	          </div>
262	        </div>
263	      </div>
264	    );
265	  }
266	
267	  return (
268	    <div className="flex h-full min-h-0 flex-1 flex-col overflow-hidden border border-border bg-surface">
269	      <BoardControls />
270	      {content}
271	    </div>
272	  );
273	}
